_L11 = [("Anchor", "Isa ang nasawi dahil sa hindi na naman pagtawid sa tamang tawiran.", "One died again because of not crossing at the proper crossing."), ("Anchor", "Isang dalawampu’t anim na anyos na lalaki ang patay matapos mahagip ng isang puting kotse at isang delivery truck pasado ala-una nang madaling-araw sa kahabaan ng Roxas Boulevard.", "A twenty-six-year-old man is dead after being hit by a white car and a delivery truck past one in the morning along Roxas Boulevard."), ("Anchor", "Kinilala ang biktima na si Eduardo Seredrica tubong Laguna.", "The victim was identified as Eduardo Seredrica, a native of Laguna."), ("Witness", "Tumatawid po siya tapos, dahil madilim, hindi po siya napansin ng ano.", "He was crossing and then, because it was dark, he was not noticed by the, um."), ("Anchor", "Nagtuturuan naman ang drayber ng kotse na si Sherwin Cabansag at ng delivery van na si Ronald Porol kung sino talaga ang tunay na nakabangga sa biktima.", "The driver of the car, Sherwin Cabansag, and the delivery van driver, Ronald Porol, are pointing fingers at each other as to who really hit the victim."), ("Anchor", "Kakasuhan ng reckless imprudence resulting to homicide ang sinumang mapapatunayang nakapatay kay Eduardo.", "Whoever is proven to have killed Eduardo will be charged with reckless imprudence resulting in homicide."), ("Officer", "Payo naman ni SPO Three Marcos Saunar ng Manila Police District, sumunod sa ano, sa tamang tawiran at dun sa mga drayber naman ng mga sasakyan dapat maging defensive drayber sila.", "The advice of SPO3 Marcos Saunar of the Manila Police District: follow the, um, proper crossing, and as for the drivers of vehicles, they should be defensive drivers."), ("Officer", "Medyo mag-ingat din sa pagpapatakbo lalo na sa madilim na lugar.", "Be a bit careful in driving too, especially in dark places."), ("Anchor", "Para sa television ng bayan, Cheska.", "For the people’s television, Cheska.")]
